object Solution {
  def numFactoredBinaryTrees(arr: Array[Int]): Int = {
    val MOD = 1000000007
    val sorted = arr.sorted
    val n = arr.length
    val dp = Array.fill[Long](n)(1L) // each single node tree counts as 1
    val indexMap = sorted.zipWithIndex.toMap

    for (i <- sorted.indices) {
      val x = sorted(i)
      for (j <- 0 until i) {
        val left = sorted(j)
        if (x % left == 0) {
          val right = x / left
          if (indexMap.contains(right)) {
            val k = indexMap(right)
            dp(i) = (dp(i) + dp(j) * dp(k)) % MOD
          }
        }
      }
    }

    dp.foldLeft(0L)((acc, v) => (acc + v) % MOD).toInt
  }
}

